import XCTest
@testable import Payments

final class RecordingLogger: PaymentLogger, @unchecked Sendable {
    private let lock = NSLock()
    private var storage: [String] = []

    var messages: [String] {
        lock.lock()
        defer { lock.unlock() }
        return storage
    }

    func info(_ message: String) {
        lock.lock()
        storage.append(message)
        lock.unlock()
    }
}

struct AcceptingGateway: PaymentGateway {
    func charge(_ request: ChargeRequest, idempotencyKey: String) async throws -> String {
        "ch_\(idempotencyKey)"
    }
}

final class ChargeServiceTests: XCTestCase {
    func testRejectsNonPositiveAmounts() async {
        let service = ChargeService(gateway: AcceptingGateway(), logger: RecordingLogger())
        let request = ChargeRequest(requestID: "req_1", customerID: "cus_1", cardNumber: "4242424242424242", amountCents: 0)
        do {
            _ = try await service.charge(request)
            XCTFail("expected invalidAmount")
        } catch {
            XCTAssertEqual(error as? ChargeError, .invalidAmount)
        }
    }
}

